// Leest het jobbestand dat de draaiende workflow bijwerkt en geeft het terug.
// Tussenstanden bevatten geen transcript of documenttekst — dat gaat pas mee in
// `resultaat` als de job klaar is, zodat het pollen licht blijft.
//
// We serialiseren hier zélf naar een string en laten de Respond-node die
// onaangeroerd doorgeven. Met respondWith=json en de expressie {{$json}} kwamen
// rauwe regeleinden uit het transcript ongeëscaped in het antwoord terecht,
// waardoor de JSON ongeldig werd en de webapp juist op de laatste poll
// struikelde. Bij een Whisper-transcript (één lange regel zonder newlines) viel
// dat niet op; bij een aangeleverd .txt-transcript wel.
const fs = require('fs');

const query = $json.query || {};
// Alleen de tekens die een job-id kan bevatten; zo kan een geknutselde
// parameter niet uit /data/shared/jobs wegwandelen.
const jobId = String(query.job || '').replace(/[^0-9A-Za-z_-]/g, '');

function antwoord(payload) {
  return [{ json: { payload: JSON.stringify(payload) } }];
}

if (!jobId) {
  return antwoord({ success: false, status: 'onbekend', fout: 'Geen job-id meegegeven.' });
}

try {
  const job = JSON.parse(fs.readFileSync(`/data/shared/jobs/${jobId}.json`, 'utf8'));
  return antwoord({ success: true, ...job });
} catch (_) {
  return antwoord({
    success: false,
    status: 'onbekend',
    fout:
      'Onbekende job. Mogelijk is n8n herstart, of is het jobbestand na de ' +
      'bewaartermijn van 24 uur opgeruimd.',
  });
}
